// The banner: art that Codex image generation makes, with the official wordmark laid over it.
//
// The art is generated by the image tool in one `codex exec` turn per theme, with the pinned
// Codex and the person's own Codex CLI sign-in (CODEX_HOME, by default ~/.codex). The prompts are
// kept outside the repository at the owner's request (TASK-161): ARCHBOARD_README_BANNER_PROMPTS
// names a directory that holds dark.txt, the prompt of the dark art, and light.txt, the prompt
// that turns the dark art into its light companion (the dark art goes to the tool as Image 1).
// Generation is not deterministic, so the PNGs in docs/assets are the canonical art: the README's
// WebPs are encoded from them.

import {
	copyFileSync,
	existsSync,
	readFileSync,
	readdirSync,
	statSync,
	writeFileSync,
} from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

import { resolveProjectCodexExecutable } from "@/runtime/codex-process/executable";

import {
	Browser,
	ffmpeg,
	holding,
	inOrder,
	inRepository,
	readmeFile,
	run,
	scratch,
	type MakeContext,
	type Producer,
	// oxlint-disable-next-line archboard/absolute-imports -- scripts/ has no alias root; @/ resolves only into src/
} from "./kit.ts";

/** The model that drives the image tool; the pixels come from the tool's own image model. */
const IMAGE_MODEL = "gpt-6.1-sol";

/** How far the wordmark sits from the art's left edge, and how wide it is, in art pixels. */
const WORDMARK = { left: 110, width: 560 } as const;

/** The wordmark's colour on each theme's art. */
const INK = { dark: "#f3f1ea", light: "#1e1e1e" } as const;

type Theme = keyof typeof INK;

/** The art and the README's banner of each theme. */
const FILES: Readonly<Record<Theme, { readonly art: string; readonly banner: string }>> = {
	dark: {
		art: "docs/assets/archboard-banner-history-dark.png",
		banner: readmeFile("banner-dark.webp"),
	},
	light: {
		art: "docs/assets/archboard-banner-history-light.png",
		banner: readmeFile("banner-light.webp"),
	},
};

/**
 * The directory of the banner's prompts.
 * @returns It.
 * @throws {Error} When it is not named or does not hold both prompts.
 */
function promptDirectory(): string {
	const named = process.env["ARCHBOARD_README_BANNER_PROMPTS"];
	if (named === undefined || named === "") {
		throw new Error(
			"The banner's prompts are kept outside the repository. Name their directory, which holds dark.txt and light.txt, in ARCHBOARD_README_BANNER_PROMPTS.",
		);
	}
	for (const theme of ["dark", "light"]) {
		if (!existsSync(join(named, `${theme}.txt`))) {
			throw new Error(`${named} holds no ${theme}.txt.`);
		}
	}
	return named;
}

/**
 * The width and height a PNG file says it has.
 * @param file The PNG.
 * @returns Its size.
 */
function pngSize(file: string): { readonly width: number; readonly height: number } {
	const header = readFileSync(file).subarray(16, 24);
	return { width: header.readUInt32BE(0), height: header.readUInt32BE(4) };
}

/**
 * Generate one image with Codex's image tool, and copy it out of Codex's home.
 * @param prompt The prompt.
 * @param out Where the image goes.
 * @param references Images the tool is given, Image 1 first.
 */
async function generate(prompt: string, out: string, references: readonly string[]): Promise<void> {
	const work = scratch("banner");
	const referenced =
		references.length === 0
			? ""
			: ` Set referenced_image_paths to exactly ${JSON.stringify(references)} (in that order, Image 1 first) and do not set num_last_images_to_include.`;
	const instruction = `Call the image_gen.imagegen tool exactly once with the prompt below, verbatim; do not rewrite, shorten or embellish it.${referenced} Do not generate any other image, do not edit files, and reply with only the saved path.\n\nPROMPT:\n${prompt}`;
	const { stdout } = await run([
		process.execPath,
		resolveProjectCodexExecutable(),
		"exec",
		"--skip-git-repo-check",
		"--ephemeral",
		"-s",
		"workspace-write",
		"-C",
		work,
		"-m",
		IMAGE_MODEL,
		"-c",
		'model_reasoning_effort="low"',
		"--json",
		instruction,
	]);
	// The turn emits no item for the image call: the image is found by the turn's thread.
	const thread = /"thread\.started".*?"thread_id":"([^"]+)"/.exec(stdout)?.[1];
	copyFileSync(newestImage(String(thread)), out);
}

/**
 * The newest image Codex saved for a thread, in its home's generated images.
 * @param thread The thread.
 * @returns The image's path.
 * @throws {Error} When the thread saved none.
 */
function newestImage(thread: string): string {
	const home = process.env["CODEX_HOME"] || join(homedir(), ".codex");
	const folder = join(home, "generated_images", thread);
	const images = existsSync(folder)
		? readdirSync(folder)
				.filter((name) => name.endsWith(".png"))
				.map((name) => join(folder, name))
		: [];
	const [newest] = images.toSorted(
		(left, right) => statSync(right).mtimeMs - statSync(left).mtimeMs,
	);
	if (newest === undefined) throw new Error(`Codex saved no image for thread ${thread}.`);
	return newest;
}

/**
 * Lay the wordmark over the art, as a page in Chromium, and save the picture.
 * @param art The art.
 * @param theme Its theme.
 * @param out Where the picture goes.
 */
async function overlayWordmark(art: string, theme: Theme, out: string): Promise<void> {
	const size = pngSize(art);
	const wordmark = readFileSync(inRepository("src/ui/shell/assets/archboard-wordmark.svg"), "utf8");
	const page = join(scratch("banner"), `${theme}.html`);
	writeFileSync(
		page,
		`<!doctype html><html><body style="margin:0;background:#000">
			<img src="${pathToFileURL(art).toString()}" style="display:block;width:${size.width}px;height:${size.height}px">
			<div style="position:absolute;left:${WORDMARK.left}px;top:50%;width:${WORDMARK.width}px;transform:translateY(-50%);color:${INK[theme]};line-height:0">${wordmark.replace("<svg ", '<svg width="100%" ')}</div>
		</body></html>`,
	);
	const browser = await Browser.start();
	await holding(
		async () => browser.close(),
		async () => {
			const window = await browser.open({ url: pathToFileURL(page).toString(), theme, ...size });
			await window.waitFor("document.images[0]?.complete", "the art");
			await window.screenshot(out);
		},
	);
}

/**
 * Generate both themes' art, lay the wordmark over it, and encode the README's banners.
 * @param context What the producer is given.
 */
async function makeBanner(context: MakeContext): Promise<void> {
	const prompts = promptDirectory();
	const work = scratch("banner");
	const dark = join(work, "dark-art.png");
	const light = join(work, "light-art.png");
	context.say("Generating the dark art with Codex image generation.");
	await generate(readFileSync(join(prompts, "dark.txt"), "utf8"), dark, []);
	context.say("Generating its light companion, with the dark art as Image 1.");
	await generate(readFileSync(join(prompts, "light.txt"), "utf8"), light, [dark]);
	const themes = [
		["dark", dark],
		["light", light],
	] as const;
	// One browser at a time keeps the machine quiet; each banner is encoded from its own art.
	await inOrder(themes, async ([theme, art]) => {
		const files = FILES[theme];
		await overlayWordmark(art, theme, inRepository(files.art));
		await ffmpeg([
			"-i",
			inRepository(files.art),
			"-c:v",
			"libwebp",
			"-quality",
			"80",
			inRepository(files.banner),
		]);
	});
}

const banner: Producer = {
	kind: "art",
	codex: true,
	files: [FILES.dark.art, FILES.light.art, FILES.dark.banner, FILES.light.banner],
	needs: ["chromium", "ffmpeg", "codex"],
	plan: [
		`Read the prompts, dark.txt and light.txt, from the directory ARCHBOARD_README_BANNER_PROMPTS names (${process.env["ARCHBOARD_README_BANNER_PROMPTS"] || "unset now"}); they are kept outside the repository.`,
		`Generate the dark art with Codex image generation (codex exec with ${IMAGE_MODEL} and the image tool, the person's own Codex CLI sign-in), then its light companion with the dark art as Image 1; this spends Codex usage.`,
		"Lay src/ui/shell/assets/archboard-wordmark.svg over each in Chromium and save the art in docs/assets.",
		"Encode each as a still WebP in docs/readme.",
	],
	make: makeBanner,
};

export { banner };
